"""Data types shared by the logger, loader, detectors and report."""

from dataclasses import asdict, dataclass, field
from typing import Any


@dataclass
class TraceRecord:
    """One LLM call, as written by the logger (one JSON line per call)."""

    run_id: str
    step: str
    call_index: int
    model: str
    input_tokens: int
    output_tokens: int  # all billed output tokens, including reasoning
    prompt: str
    output: str
    cached_input_tokens: int = 0
    reasoning_tokens: int = 0  # billed "thinking" tokens, part of output_tokens
    latency_ms: int = 0
    timestamp: str = ""
    case_id: str = ""  # same input across runs, so before/after can be paired
    extra: dict[str, Any] = field(default_factory=dict)

    @property
    def visible_output_tokens(self) -> int:
        return max(self.output_tokens - self.reasoning_tokens, 0)

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> "TraceRecord":
        known = set(cls.__dataclass_fields__) - {"extra"}
        kwargs = {k: v for k, v in data.items() if k in known}
        kwargs["extra"] = {k: v for k, v in data.items() if k not in known}
        return cls(**kwargs)

    def to_dict(self) -> dict[str, Any]:
        data = asdict(self)
        extra = data.pop("extra")
        data.update(extra)
        return data


@dataclass
class CallChange:
    """How a fix changes one call. Detectors emit these so totals never double count."""

    new_model: str | None = None  # price the call at this model instead
    drop_reasoning: bool = False  # the cheaper model doesn't spend thinking tokens
    cached_tokens: int = 0  # input tokens that would be billed at the cached rate
    removed_input_tokens: int = 0  # input tokens that would no longer be sent
    removed: bool = False  # the whole call would not happen


@dataclass
class Finding:
    run_id: str
    step: str
    detector: str
    evidence: str
    cost_now: float
    cost_after: float
    suggestion: str
    calls: list[int] = field(default_factory=list)
    changes: dict[int, CallChange] = field(default_factory=dict)

    @property
    def saving(self) -> float:
        return self.cost_now - self.cost_after

    def to_dict(self) -> dict[str, Any]:
        return {
            "run_id": self.run_id,
            "step": self.step,
            "detector": self.detector,
            "evidence": self.evidence,
            "cost_now": round(self.cost_now, 6),
            "cost_after": round(self.cost_after, 6),
            "suggestion": self.suggestion,
            "calls": self.calls,
        }

"""Prices from pricing.yaml. All costs in the report are computed here."""

from dataclasses import dataclass
from pathlib import Path

import yaml

from .records import CallChange, TraceRecord

PER_TOKEN = 1_000_000
DEFAULT_PATH = Path(__file__).resolve().parent.parent / "pricing.yaml"


@dataclass(frozen=True)
class ModelPrice:
    tier: str
    reasoning: bool
    input: float
    output: float
    cached_input: float


class UnknownModelError(KeyError):
    pass


class Pricing:
    def __init__(self, models: dict[str, ModelPrice], source: str = ""):
        self.models = models
        self.source = source

    @classmethod
    def load(cls, path: str | Path = DEFAULT_PATH) -> "Pricing":
        data = yaml.safe_load(Path(path).read_text(encoding="utf-8"))
        models = {
            name: ModelPrice(
                tier=m["tier"],
                reasoning=bool(m.get("reasoning", False)),
                input=float(m["input"]),
                output=float(m["output"]),
                cached_input=float(m["cached_input"]),
            )
            for name, m in data["models"].items()
        }
        return cls(models, data.get("source", ""))

    def get(self, model: str) -> ModelPrice:
        # Providers sometimes report "models/<name>" or a dated suffix.
        name = model.removeprefix("models/")
        if name in self.models:
            return self.models[name]
        for known in self.models:
            if name.startswith(known):
                return self.models[known]
        raise UnknownModelError(f"No price for model {model!r}; add it to pricing.yaml")

    def tier(self, model: str) -> str:
        return self.get(model).tier

    def cost(
        self,
        model: str,
        input_tokens: int,
        output_tokens: int,
        cached_input_tokens: int = 0,
    ) -> float:
        p = self.get(model)
        cached = min(cached_input_tokens, input_tokens)
        return (
            (input_tokens - cached) * p.input
            + cached * p.cached_input
            + output_tokens * p.output
        ) / PER_TOKEN

    def call_cost(self, rec: TraceRecord) -> float:
        return self.cost(rec.model, rec.input_tokens, rec.output_tokens, rec.cached_input_tokens)

    def changed_cost(self, rec: TraceRecord, change: CallChange) -> float:
        """Cost of a call after a fix is applied."""
        if change.removed:
            return 0.0
        model = change.new_model or rec.model
        output = rec.visible_output_tokens if change.drop_reasoning else rec.output_tokens
        input_tokens = max(rec.input_tokens - change.removed_input_tokens, 0)
        cached = min(rec.cached_input_tokens + change.cached_tokens, input_tokens)
        return self.cost(model, input_tokens, output, cached)

"""Loads trace records. Detectors only see TraceRecords, never where they came from."""

import json
from collections import defaultdict
from pathlib import Path

from .records import TraceRecord


def load_jsonl(path: str | Path) -> list[TraceRecord]:
    records = []
    with Path(path).open(encoding="utf-8") as f:
        for line_no, line in enumerate(f, 1):
            line = line.strip()
            if not line:
                continue
            try:
                records.append(TraceRecord.from_dict(json.loads(line)))
            except (json.JSONDecodeError, TypeError) as e:
                raise ValueError(f"{path}:{line_no}: bad trace record ({e})") from e
    return records


def group_by_run(records: list[TraceRecord]) -> dict[str, list[TraceRecord]]:
    runs: dict[str, list[TraceRecord]] = defaultdict(list)
    for rec in records:
        runs[rec.run_id].append(rec)
    for calls in runs.values():
        calls.sort(key=lambda r: r.call_index)
    return dict(runs)


def load_runs(*paths: str | Path) -> dict[str, list[TraceRecord]]:
    records = [rec for path in paths for rec in load_jsonl(path)]
    return group_by_run(records)

from pathlib import Path
from typing import Any

import yaml

DEFAULT_PATH = Path(__file__).resolve().parent.parent / "config.yaml"


def load_config(path: str | Path = DEFAULT_PATH) -> dict[str, Any]:
    return yaml.safe_load(Path(path).read_text(encoding="utf-8"))

"""Detector 3: the same request made more than once in a run."""

import hashlib
import re
from difflib import SequenceMatcher

from ..pricing import Pricing
from ..records import CallChange, Finding, TraceRecord

NAME = "redundant_calls"


def normalise(prompt: str) -> str:
    return re.sub(r"\s+", " ", prompt).strip().lower()


def _similar(a: str, b: str, threshold: float) -> bool:
    if a == b:
        return True
    if min(len(a), len(b)) / max(len(a), len(b), 1) < threshold:
        return False
    m = SequenceMatcher(None, a, b, autojunk=False)
    return m.real_quick_ratio() >= threshold and m.quick_ratio() >= threshold and m.ratio() >= threshold


def find_duplicate_groups(calls: list[TraceRecord], threshold: float) -> list[list[TraceRecord]]:
    """Groups of calls to the same model with the same (or near-identical) prompt."""
    norm = [normalise(c.prompt) for c in calls]
    digest = [hashlib.sha256(n.encode()).hexdigest() for n in norm]

    parent = list(range(len(calls)))

    def root(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    for i in range(len(calls)):
        for j in range(i + 1, len(calls)):
            if calls[i].model != calls[j].model:
                continue
            if digest[i] == digest[j] or _similar(norm[i], norm[j], threshold):
                parent[root(j)] = root(i)

    groups: dict[int, list[TraceRecord]] = {}
    for i, c in enumerate(calls):
        groups.setdefault(root(i), []).append(c)
    return [g for g in groups.values() if len(g) > 1]


def detect(run_id: str, calls: list[TraceRecord], pricing: Pricing, cfg: dict) -> list[Finding]:
    findings = []
    for group in find_duplicate_groups(calls, cfg["similarity"]):
        first, dupes = group[0], group[1:]
        cost_now = sum(pricing.call_cost(c) for c in dupes)
        steps = sorted({c.step for c in group}, key=[c.step for c in group].index)
        exact = all(normalise(c.prompt) == normalise(first.prompt) for c in dupes)
        findings.append(
            Finding(
                run_id=run_id,
                step=", ".join(steps),
                detector=NAME,
                evidence=f"{'Identical' if exact else 'Near-identical'} request to {first.model} "
                f"made {len(group)} times (calls {', '.join(str(c.call_index) for c in group)})",
                cost_now=cost_now,
                cost_after=0.0,
                suggestion=f"Reuse the result of the first {first.step} call instead of asking again.",
                calls=[c.call_index for c in dupes],
                changes={c.call_index: CallChange(removed=True) for c in dupes},
            )
        )
    return findings

"""Runs the detectors over each run and totals cost before and after all fixes."""

from dataclasses import dataclass, field

from .detectors import DETECTORS
from .pricing import Pricing
from .records import CallChange, Finding, TraceRecord


@dataclass
class RunAnalysis:
    run_id: str
    case_id: str
    calls: list[TraceRecord]
    findings: list[Finding]
    cost_now: float
    cost_after: float
    call_costs_after: dict[int, float] = field(default_factory=dict)

    @property
    def saving(self) -> float:
        return self.cost_now - self.cost_after

    @property
    def percent_saved(self) -> float:
        return 100 * self.saving / self.cost_now if self.cost_now else 0.0


def merge_changes(changes: list[CallChange]) -> CallChange:
    """Combine every fix that touches one call (e.g. cheaper model AND cached prefix)."""
    merged = CallChange()
    for c in changes:
        merged.removed |= c.removed
        merged.drop_reasoning |= c.drop_reasoning
        merged.new_model = c.new_model or merged.new_model
        merged.cached_tokens += c.cached_tokens
        merged.removed_input_tokens += c.removed_input_tokens
    return merged


def analyze_run(run_id: str, calls: list[TraceRecord], pricing: Pricing, config: dict) -> RunAnalysis:
    findings: list[Finding] = []
    for section, detector in DETECTORS:
        findings.extend(detector.detect(run_id, calls, pricing, config[section]))
    findings.sort(key=lambda f: f.saving, reverse=True)

    per_call: dict[int, list[CallChange]] = {}
    for f in findings:
        for idx, change in f.changes.items():
            per_call.setdefault(idx, []).append(change)

    costs_after = {}
    for rec in calls:
        changes = per_call.get(rec.call_index)
        costs_after[rec.call_index] = (
            pricing.changed_cost(rec, merge_changes(changes)) if changes else pricing.call_cost(rec)
        )

    return RunAnalysis(
        run_id=run_id,
        case_id=calls[0].case_id if calls else "",
        calls=calls,
        findings=findings,
        cost_now=sum(pricing.call_cost(r) for r in calls),
        cost_after=sum(costs_after.values()),
        call_costs_after=costs_after,
    )


def analyze(runs: dict[str, list[TraceRecord]], pricing: Pricing, config: dict) -> list[RunAnalysis]:
    return [analyze_run(run_id, calls, pricing, config) for run_id, calls in runs.items()]


def measured_cost(calls: list[TraceRecord], pricing: Pricing) -> float:
    return sum(pricing.call_cost(r) for r in calls)

